// Furniture models generated by the server (Blender → GLB), with the browser's own model as
// the fallback while one is built, or when the server has no Blender.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.js';
import { rel, type ModelInfo, type Product } from '@/api';

const draco = new DRACOLoader().setDecoderPath('draco/').setDecoderConfig({ type: 'js' });
const loader = new GLTFLoader().setDRACOLoader(draco);

const scenes = new Map<string, Promise<THREE.Group | null>>();
let unavailable = false;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function info(p: Product, retry = false): Promise<ModelInfo> {
  const res = await fetch(`api/models${retry ? '?retry=1' : ''}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(p) });
  if (!res.ok) return { available: false };
  return res.json();
}

/** Where the GLB for a product is, once it exists; null when there will be none. */
async function urlFor(p: Product): Promise<string | null> {
  if (unavailable) return null;
  let i = await info(p);
  if (!i.available) {
    unavailable = true;
    return null;
  }
  for (let n = 0; !i.ready && n < 60; n++) {
    if (i.error) return null;
    await sleep(1000);
    i = await info(p);
  }
  return i.ready && i.url ? i.url : null;
}

function load(url: string): Promise<THREE.Group> {
  return new Promise((resolve, reject) => loader.load(rel(url), (g) => resolve(g.scene), undefined, reject));
}

/** The generated model of a product, sized and lit for the scene, or null. */
export function generated(p: Product): Promise<THREE.Group | null> {
  const key = `${p.type}:${p.w}:${p.d}:${p.h}:${p.colorHex}:${p.name}`;
  let pr = scenes.get(key);
  if (!pr) {
    pr = urlFor(p)
      .then((u) => (u ? load(u) : null))
      .then((s) => {
        s?.traverse((o) => {
          const m = o as THREE.Mesh;
          if (m.isMesh) {
            m.castShadow = p.type !== 'rug';
            m.receiveShadow = true;
          }
        });
        return s;
      })
      .catch(() => null);
    scenes.set(key, pr);
  }
  return pr.then((s) => (s ? s.clone(true) : null));
}

// Polyfork's Open Plan kit (CC BY 4.0, credits in /models/polyfork/CREDITS.txt): one palette
// and one scale for the furniture and fixtures it has, front +Z.
const KIT = new Set(['sofa', 'tvbench', 'rug', 'bed', 'wardrobe', 'desk', 'bookcase', 'armchair', 'table', 'chair', 'lamp', 'drawers', 'toilet', 'basin', 'shower', 'counter', 'fridge']);

/** The kit's model for a kind of furniture or fixture, if it has one. */
export const kitUrl = (kind: string): string | null => (KIT.has(kind) ? `models/polyfork/${kind}.glb` : null);

/** A model stretched to w × h × d metres, standing on the origin at its floor centre. */
export async function fitted(url: string, w: number, h: number, d: number): Promise<THREE.Group | null> {
  const g = await prop(url);
  if (!g) return null;
  const box = new THREE.Box3().setFromObject(g);
  const size = box.getSize(new THREE.Vector3());
  const c = box.getCenter(new THREE.Vector3());
  g.position.set(-c.x, -box.min.y, -c.z);
  const out = new THREE.Group();
  out.add(g);
  out.scale.set(w / size.x, h / size.y, d / size.z);
  return out;
}

export async function prop(url: string): Promise<THREE.Group | null> {
  let pr = scenes.get(url);
  if (!pr) {
    pr = load(url).then((s) => {
      s.traverse((o) => { if ((o as THREE.Mesh).isMesh) { (o as THREE.Mesh).castShadow = true; (o as THREE.Mesh).receiveShadow = true; } });
      return s;
    }).catch(() => null);
    scenes.set(url, pr);
  }
  return pr.then((s) => (s ? s.clone(true) : null));
}
